capabilities.command:
set -euo pipefail
AUTODOC_NOTEBOOKS_REPO_URL="$NOTEBOOKS_REPO_INPUT"
AUTODOC_NOTEBOOKS_BRANCH="$NOTEBOOKS_BRANCH_INPUT"
if [[ "$GITHUB_REF" == refs/pull* ]]; then
AUTODOC_NOTEBOOKS_REPO_URL=${AUTODOC_NOTEBOOKS_REPO_URL:-"$GITHUB_SERVER_URL/$PR_HEAD_REPOSITORY"}
AUTODOC_NOTEBOOKS_BRANCH=${AUTODOC_NOTEBOOKS_BRANCH:-$GITHUB_HEAD_REF}
elif [[ "$GITHUB_REF" == refs/heads* ]]; then
AUTODOC_NOTEBOOKS_REPO_URL=${AUTODOC_NOTEBOOKS_REPO_URL:-"$GITHUB_SERVER_URL/$GITHUB_REPOSITORY"}
AUTODOC_NOTEBOOKS_BRANCH=${AUTODOC_NOTEBOOKS_BRANCH:-${GITHUB_REF#refs/heads/}}
elif [[ "$GITHUB_REF" == refs/tags* ]]; then
AUTODOC_NOTEBOOKS_REPO_URL=${AUTODOC_NOTEBOOKS_REPO_URL:-"$GITHUB_SERVER_URL/$GITHUB_REPOSITORY"}
AUTODOC_NOTEBOOKS_BRANCH=${AUTODOC_NOTEBOOKS_BRANCH:-${GITHUB_REF#refs/tags/}}
fi
echo "AUTODOC_NOTEBOOKS_REPO_URL=$AUTODOC_NOTEBOOKS_REPO_URL" >> "$GITHUB_ENV"
echo "AUTODOC_NOTEBOOKS_BRANCH=$AUTODOC_NOTEBOOKS_BRANCH" >> "$GITHUB_ENV"
echo "Notebooks source: $AUTODOC_NOTEBOOKS_REPO_URL/tree/$AUTODOC_NOTEBOOKS_BRANCH"

$vsPath = & "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\vswhere.exe" -latest -property installationPath
$vcvarsall = Join-Path $vsPath "VC\Auxiliary\Build\vcvarsall.bat"
cmd /c "`"$vcvarsall`" amd64 >nul && set" | ForEach-Object {
if ($_ -match '^(PATH|INCLUDE|LIB|LIBPATH)=(.*)$') {
"$($Matches[1])=$($Matches[2])" >> $env:GITHUB_ENV
}
}

import ast
from pathlib import Path

banned_names = {"Mock", "MagicMock", "patch", "monkeypatch"}
violations = []
for path in sorted(Path("tests/powl").glob("test_runner*.py")):
tree = ast.parse(path.read_text(), filename=str(path))
for node in ast.walk(tree):
if isinstance(node, ast.Import):
for alias in node.names:
if alias.name == "unittest.mock":
violations.append((path, node.lineno, f"import {alias.name}"))
elif isinstance(node, ast.ImportFrom):
if node.module == "unittest.mock":
violations.append((path, node.lineno, "from unittest.mock import ..."))
elif isinstance(node, ast.Name) and node.id in banned_names:
violations.append((path, node.lineno, node.id))
elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
args = (*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs)
for arg in args:
if arg.arg == "monkeypatch":
violations.append((path, node.lineno, "monkeypatch fixture"))
if violations:
for path, line, detail in violations:
print(f"{path}:{line}: banned mockist construct: {detail}")
raise SystemExit(1)

from pathlib import Path
roots = (Path("src"), Path("tests"), Path("examples"))
for root in roots:
for path in root.rglob("*.py"):
compile(path.read_bytes(), str(path), "exec")
